for module in details['agroBusinessModules']+details['agroModules']:
    sia_lines += ['## '+module['title'],'','**Domínio:** '+module['domain']+'.','','**Finalidade:** '+module['objective']+'.','','**Habilidades:** '+'; '.join(module['skills'])+'.','','**Stack:** '+', '.join(module['stack'])+'.','','**Sinais da implementação:** '+'; '.join(module['implementationSignals'])+'.','','**Fontes:** '+', '.join('`'+s['path']+':'+str(s['line'])+'`' for s in module['sources'])+'.','','**Estado e limite:** '+module['status']+'.','']
(BASE/'SIA_MODULOS_E_COMPETENCIAS.md').write_text('\n'.join(sia_lines),encoding='utf-8')
